//! Where libmpv is, and the cache policy.
//!
//! The path comes from the environment (`RONOCTUA_LIBMPV_DIR`, set by
//! `nix/rust.nix` and the devshell) and goes into the binary's RUNPATH, so
//! the daemon finds the SAME libmpv it was linked against and never a
//! system one.
//!
//! The cache policy is generated by Nix out of `assets/cache.nix`
//! (`RONOCTUA_CACHE_RS`) and copied into `OUT_DIR`, as every crate that
//! reads it does: the subtitles the daemon keeps are bounded there
//! (`engine/subtitles.rs`). Generating it here would leave the one source of
//! truth and reimplement Nix logic (invariant 5).

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo::rerun-if-env-changed=RONOCTUA_LIBMPV_DIR");
    if let Ok(dir) = env::var("RONOCTUA_LIBMPV_DIR") {
        println!("cargo::rustc-link-search=native={dir}");
        // EVERY artefact, the tests included: a test binary that cannot find
        // libmpv at run time fails before it tests anything.
        println!("cargo::rustc-link-arg=-Wl,-rpath,{dir}");
    }

    println!("cargo::rerun-if-env-changed=RONOCTUA_CACHE_RS");
    let generated = env::var("RONOCTUA_CACHE_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_CACHE_RS is not set.\n\
             \n\
             The cache policy is generated by Nix out of assets/cache.nix.\n\
             Enter the environment with `direnv allow` (or `nix develop`), which\n\
             sets the variable, or build through the flake with `nix build`."
        )
    });
    println!("cargo::rerun-if-changed={generated}");
    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("cache.rs");
    // DELETE FIRST: the file comes from the store read-only, and `fs::copy`
    // inherits the mode along with the content — the second build fails with
    // "Permission denied" inside a build script.
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
